import{_ as t,c as o,o as a,ae as i}from"./chunks/framework.CliRSA9F.js";const s="/images/social_publishing.webp",g=JSON.parse('{"title":"Social Publishing","description":"","frontmatter":{},"headers":[],"relativePath":"features/social-publishing.md","filePath":"features/social-publishing.md"}'),n={name:"features/social-publishing.md"};function r(l,e,h,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="social-publishing" tabindex="-1">Social Publishing <a class="header-anchor" href="#social-publishing" aria-label="Permalink to &quot;Social Publishing&quot;">​</a></h1><h2 id="turn-episodes-into-short-video-clips-and-publish-them" tabindex="-1">Turn Episodes into Short Video Clips and Publish Them <a class="header-anchor" href="#turn-episodes-into-short-video-clips-and-publish-them" aria-label="Permalink to &quot;Turn Episodes into Short Video Clips and Publish Them&quot;">​</a></h2><p>Social Publishing helps you repurpose your podcast episodes into short, vertical video clips — the kind of reels that perform well on social platforms — and publish them where new listeners are most likely to discover you. Instead of editing video by hand, you let PodSEO find the strongest moments in an episode, turn them into ready-to-share clips, and post them directly to your connected social accounts.</p><p><img src="'+s+'" alt="Social Publishing Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Social Publishing</strong> in the sidebar. You can also reach it from the <strong>Planner</strong> — the <strong>Social Publishing</strong> button in the Planner&#39;s view switcher opens the same page.</p><p>Social Publishing has three tabs:</p><ul><li><strong>Social Publishing</strong> — Your social calendar, connected accounts, Autopilot, and recent posts</li><li><strong>Create</strong> — Create new clips from your episodes and follow their progress as highlights and videos are generated</li><li><strong>Media library</strong> — Manage your finished clips and reusable media (including custom backgrounds on paid plans), and turn finished clips into social posts</li></ul><h2 id="why-social-publishing-matters" tabindex="-1">Why Social Publishing Matters <a class="header-anchor" href="#why-social-publishing-matters" aria-label="Permalink to &quot;Why Social Publishing Matters&quot;">​</a></h2><p>Audio alone limits how far an episode can travel. Short video clips give your best moments a second life on platforms built for discovery, helping you:</p><ul><li><strong>Reach new listeners</strong> who find you through video feeds rather than podcast apps</li><li><strong>Promote new episodes</strong> with shareable highlights instead of plain links</li><li><strong>Stay consistent on social</strong> without spending hours on editing</li><li><strong>Drive traffic back to your show</strong> from the platforms your audience already uses</li></ul><p>Plan clips, captions, and channels in one place, then schedule everything from a single calendar.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Social Publishing follows a simple path: find the best moments in an episode, turn them into a video clip, then write a caption and publish the clip to your chosen platforms.</p><h3 id="step-1-find-social-clip-highlights" tabindex="-1">Step 1: Find Social Clip Highlights <a class="header-anchor" href="#step-1-find-social-clip-highlights" aria-label="Permalink to &quot;Step 1: Find Social Clip Highlights&quot;">​</a></h3><p>Start from a published episode. PodSEO reviews the episode and selects the three best moments for social clips — the segments most likely to capture attention. Before highlights are generated, you&#39;ll confirm that you have the rights or permission to create clips from the episode.</p><h3 id="step-2-review-the-moments-and-generate-video" tabindex="-1">Step 2: Review the Moments and Generate Video <a class="header-anchor" href="#step-2-review-the-moments-and-generate-video" aria-label="Permalink to &quot;Step 2: Review the Moments and Generate Video&quot;">​</a></h3><p>Once the highlights are ready, review the selected moments and choose which ones to turn into finished videos. For each clip you can adjust how the video looks — choosing a background, deciding whether to show your show cover, and toggling visual touches like a waveform — before generating the final vertical video. Paid plans can also upload their own custom backgrounds for clips. If a result isn&#39;t quite right, you can generate it again with different settings.</p><h3 id="step-3-create-a-social-post" tabindex="-1">Step 3: Create a Social Post <a class="header-anchor" href="#step-3-create-a-social-post" aria-label="Permalink to &quot;Step 3: Create a Social Post&quot;">​</a></h3><p>With a finished clip in hand, create a social post:</p><ol><li><strong>Attach your clip</strong> — A completed clip is required before a post can be scheduled or published.</li><li><strong>Write a caption</strong> — Add the copy you want to appear with the post. PodSEO adds <strong>#Shorts</strong> to YouTube captions automatically if it isn&#39;t already there, and on free plans, Instagram captions automatically credit <strong>@podseo.app</strong>.</li><li><strong>Choose destinations</strong> — Select which connected platforms the clip should go to.</li><li><strong>Publish or schedule</strong> — Publish now, or pick a date and time to post later.</li></ol><p>You can also save a post as a draft while a clip is still being made, then come back to attach the clip and finish scheduling.</p><h2 id="credits-how-clip-creation-is-paid-for" tabindex="-1">Credits: How Clip Creation Is Paid For <a class="header-anchor" href="#credits-how-clip-creation-is-paid-for" aria-label="Permalink to &quot;Credits: How Clip Creation Is Paid For&quot;">​</a></h2><p>Social Publishing runs on <strong>credits</strong>. Two actions use them:</p><ul><li><strong>Analyzing an episode</strong> to find its best moments — 5 credits per episode</li><li><strong>Generating a clip</strong> from one of those moments — 5 credits per clip</li></ul><p>So a typical episode — one analysis plus three clips — uses 20 credits. Regenerating a clip with a different look counts as a new clip.</p><p><strong>Monthly allowance.</strong> Every plan includes a monthly credit allowance that refreshes at the start of each calendar month: Free 10, Podcaster 50, Producer 250, Agency 750, Enterprise 1,500. Unused monthly credits don&#39;t roll over.</p><p><strong>Buying more.</strong> If you need more than your allowance, click <strong>Add credits</strong> (from the credit indicator or <strong>Settings → Credits</strong>) to buy a one-time pack of 50, 100, or 250 credits, or upgrade your plan for a larger monthly allowance. Purchased credits — along with credits you earn by completing the setup steps in the <a href="/features/command-center.html">Command Center</a> — don&#39;t expire with the monthly reset and are used after your monthly credits run out.</p><p><strong>Where to see your balance.</strong> Your available credits appear in the header of the app; hover or tap the indicator for a breakdown. <strong>Settings → Credits</strong> shows the current period&#39;s available, reserved, monthly, and <strong>Purchased + earned credits</strong>, plus a full history of every credit added, reserved, spent, refunded, or adjusted.</p><p><strong>When credits run out.</strong> You can still review moments you&#39;ve already analyzed, edit captions, schedule posts, and publish clips that are already made — publishing itself doesn&#39;t use credits. Analyzing a new episode or generating a new clip will ask you to add credits or wait for the next monthly refresh. If Autopilot is on, it turns itself off when there aren&#39;t enough credits for its next action and emails you so you can top up and re-enable it.</p><h2 id="publishing-limits" tabindex="-1">Publishing Limits <a class="header-anchor" href="#publishing-limits" aria-label="Permalink to &quot;Publishing Limits&quot;">​</a></h2><p>Separately from credits, each plan has a cap on how many <strong>destinations</strong> you can publish to per day, per week, and per month (a post sent to two platforms counts as two destinations), plus a short-burst limit to prevent accidental floods. Free accounts have the smallest caps and paid plans raise them progressively. The app tells you when a publish would exceed a limit, and scheduled posts count toward the window in which they&#39;re due to go out.</p><h2 id="autopilot" tabindex="-1">Autopilot <a class="header-anchor" href="#autopilot" aria-label="Permalink to &quot;Autopilot&quot;">​</a></h2><p>The <strong>Autopilot</strong> panel on the Social Publishing page does the manual workflow for you:</p><ul><li><strong>New episodes.</strong> When PodSEO detects a newly published episode, Autopilot analyzes it, creates up to three clips, and schedules them across the following week to the destinations you&#39;ve selected — using your credits (typically 20 per episode). Autopilot picks posting times from recommended publishing windows for the weekday and your chosen timezone, skipping slots you&#39;ve already scheduled; check the calendar to see exactly when each post will go out.</li><li><strong>Destinations.</strong> Tick which connected accounts Autopilot may post to. You need at least one connected destination before you can enable it.</li><li><strong>Timezone.</strong> Autopilot picks posting times in the timezone shown in the panel; click <strong>Change</strong> to set a different one. Existing scheduled posts keep their times.</li><li><strong>Keep posting when quiet.</strong> Optionally, when no new-episode posts are scheduled, Autopilot schedules one clip from your back catalog every 3, 7, or 14 days or every 4 weeks. Each catalog post uses credits too (analysis plus one clip if the episode hasn&#39;t been analyzed yet).</li><li><strong>Cost estimate.</strong> The panel shows the credits per new episode and an estimated monthly total based on your publishing frequency and cadence, so you can see whether your allowance covers it before saving.</li><li><strong>Visibility.</strong> Autopilot posts are public by default, using each platform&#39;s normal posting settings.</li></ul><p>You can edit draft and scheduled posts before they begin publishing. Check their current status on the calendar. Turning Autopilot off stops future automatic work; review existing scheduled posts separately if you want to cancel them.</p><h2 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h2><p>Connect destinations from the Social Publishing page: <strong>YouTube Shorts, LinkedIn, Bluesky, Instagram, Threads, Facebook</strong>, and <strong>TikTok</strong>. TikTok requires a paid plan and a clip without a watermark; other destinations remain subject to your account permissions and publishing limits.</p><p>Choose the destination card, complete the platform&#39;s connection flow, and select that account when creating a post or configuring Autopilot. For YouTube, Google shows an account chooser: pick the Google account (or Brand Account) that owns your channel. If the account you pick has no YouTube channel, PodSEO tells you so and you can connect again with the right account, or create a channel at youtube.com first. If the card asks you to reconnect, renew access before scheduling more posts. Connecting an account does not publish anything by itself.</p><p>If a post fails, open its status and read the destination-specific message. Check the connection, media requirements, credit balance for unfinished clips, and publishing limits before retrying. For a post sent to multiple destinations, check which ones succeeded so you do not publish duplicates. <a href="/features/agency-workspace.html#request-episode-and-social-post-approvals">Agency approvals</a> must also be satisfied where a review is required.</p><h2 id="the-social-calendar" tabindex="-1">The Social Calendar <a class="header-anchor" href="#the-social-calendar" aria-label="Permalink to &quot;The Social Calendar&quot;">​</a></h2><p>Scheduled and draft posts appear on the Social Publishing calendar, which you can view by month or by week. This gives you a clear picture of what&#39;s going out and when, so you can keep a steady cadence of social content alongside your episode publishing schedule. Recent clips and recently published posts are also surfaced so you can reuse or follow up on them quickly.</p><h2 id="how-to-use-social-publishing-effectively" tabindex="-1">How to Use Social Publishing Effectively <a class="header-anchor" href="#how-to-use-social-publishing-effectively" aria-label="Permalink to &quot;How to Use Social Publishing Effectively&quot;">​</a></h2><h3 id="lead-with-your-strongest-moments" tabindex="-1">Lead With Your Strongest Moments <a class="header-anchor" href="#lead-with-your-strongest-moments" aria-label="Permalink to &quot;Lead With Your Strongest Moments&quot;">​</a></h3><p>Let PodSEO surface the highlights, then pick the clips that best represent what makes your show worth listening to. A single compelling moment often travels further than a longer, less focused segment.</p><h3 id="tailor-captions-to-each-audience" tabindex="-1">Tailor Captions to Each Audience <a class="header-anchor" href="#tailor-captions-to-each-audience" aria-label="Permalink to &quot;Tailor Captions to Each Audience&quot;">​</a></h3><p>Write captions that give viewers a reason to watch and a clear next step — like listening to the full episode. A strong caption paired with a great clip is what turns a casual viewer into a new listener.</p><h3 id="build-a-posting-rhythm" tabindex="-1">Build a Posting Rhythm <a class="header-anchor" href="#build-a-posting-rhythm" aria-label="Permalink to &quot;Build a Posting Rhythm&quot;">​</a></h3><p>Use the calendar to schedule clips in advance rather than posting sporadically. Consistency helps your content perform better over time and keeps your show visible between episodes.</p><h3 id="repurpose-across-platforms" tabindex="-1">Repurpose Across Platforms <a class="header-anchor" href="#repurpose-across-platforms" aria-label="Permalink to &quot;Repurpose Across Platforms&quot;">​</a></h3><p>The same clip can reach different audiences on different platforms. Publishing one strong clip to several connected destinations is an efficient way to maximize the reach of every episode.</p><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><ul><li><strong><a href="/features/planner.html">Planner</a></strong> — A <strong>Social Publishing</strong> button in the Planner&#39;s view switcher links straight to this page, so clip creation fits naturally into your episode workflow</li><li><strong><a href="/features/pulse.html">Pulse</a></strong> — Timely episodes inspired by trending topics make especially shareable clips</li><li><strong><a href="/features/youtube-insights.html">YouTube Insights</a></strong> — Your YouTube connection also powers YouTube Insights: activate it to see the searches that bring viewers to your channel and get keyword suggestions for your video titles. Disconnecting the YouTube account here also stops YouTube Insights and deletes its data</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Social Publishing is available to all accounts. Free accounts receive a small monthly credit allowance and lower publishing caps, and finished videos carry a PodSEO watermark. Free accounts&#39; Instagram captions also credit @podseo.app. Paid plans remove the watermark and the caption credit, include a larger monthly credit allowance and higher publishing caps, support custom clip backgrounds, and can buy extra credit packs. TikTok publishing requires a paid plan and unwatermarked clips.</p><hr><h3 id="pro-tips" tabindex="-1">Pro Tips <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;Pro Tips&quot;">​</a></h3><ul><li>Confirm you have the rights to an episode&#39;s audio before creating clips from it</li><li>Generate a clip again with a different background or style if the first version doesn&#39;t feel on-brand</li><li>Save drafts early — you can write captions and choose destinations even before a clip is fully ready</li><li>Schedule clips around your episode releases so each new episode gets a promotional push</li><li>Check your credit balance before analyzing a long back catalog — each episode costs credits to analyze even if you only generate one clip</li><li>If you enable Autopilot&#39;s &quot;Keep posting when quiet&quot; cadence, use the panel&#39;s monthly estimate to make sure your allowance covers both new episodes and catalog posts</li></ul><p>Social Publishing turns the work you&#39;ve already done into shareable video, helping every episode reach beyond your podcast feed and bring new listeners back to your show.</p>',58)])])}const m=t(n,[["render",r]]);export{g as __pageData,m as default};
